css:
.is { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 16px; }
.is__card { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 10px; padding: 32px 20px 36px; border-radius: var(--radius-card); border: 1px solid rgba(255, 255, 255, 0.12); background: rgba(255, 255, 255, 0.02); color: #fff; }
.is__ring { display: grid; place-items: center; width: 56px; height: 56px; border-radius: 50%; border: 1px solid rgba(255, 255, 255, 0.55); margin-bottom: 10px; }
.is__glyph { display: block; width: 20px; height: 20px; background: currentColor; -webkit-mask: no-repeat center / contain; mask: no-repeat center / contain; }
.is__v { font: 700 28px / 1.1 var(--font-heading); }
.is__l { font-size: 14px; color: rgba(255, 255, 255, 0.82); }
